/**
 * Refuse a launch past the host-enforced delegation depth limit. The depth is
 * read from this session's own environment; see maestro/core/delegation-depth.ts.
 */
export function delegationDepthRefusal(
	maxDepth: number,
	env: NodeJS.ProcessEnv = process.env,
): { message: string; code: string } | undefined {
	const decision = decideDelegation(
		parseDelegationDepth(env[DELEGATION_DEPTH_ENV]),
		maxDepth,
	);
	return decision.allowed
		? undefined
		: { message: decision.message, code: `delegation-${decision.reason}` };
}

/**
 * Register a public spawn/resume tool whose failures are encoded exactly once
 * at this boundary. Routing, adapter, Git and worktree errors carry raw values
 * (paths, role models, Git output) that may hold line breaks, separators or
 * report delimiters, so the thrown tool error is one encoded line; the raw
 * error stays its `cause`.
 */
function muxUnavailableResult(runtime: SubagentRuntime) {
	return {
		content: [
			{
				type: "text" as const,
				text: `Subagents require herdr. ${runtime.session!.availability().setupHint}`,
			},
		],
		details: { error: "herdr not available" },
	};
}

interface LaunchToolDeps {
	renderers?: PiToolRenderers;
	shouldRegister: (name: string) => boolean;
	runtime: SubagentRuntime;
	updateWidget: () => void;
	subagentRoutingGuidelines: string[];
	persistentCapacityError: PersistentControls["persistentCapacityError"];
	resolveSubagentRuntimePlans: LaunchPlanner["resolveSubagentRuntimePlans"];
	normalizePiAttempt: LaunchPlanner["normalizePiAttempt"];
	spawningConfig: SpawningConfig;
}

/** The subagent launch tool. */
export function registerSubagentTool(
	pi: ExtensionAPI,
	{
		shouldRegister,
		runtime,
		updateWidget,
		subagentRoutingGuidelines,
		renderers,
		persistentCapacityError,
		resolveSubagentRuntimePlans,
		normalizePiAttempt,
		spawningConfig,
	}: LaunchToolDeps,
): void {
	const runningSubagents = runtime.runningSubagents;

	// ── subagent tool ──
	if (shouldRegister("subagent"))
		pi.registerTool({
			name: "subagent",
			exposure: ROUTINE_TOOL_EXPOSURE,
			label: "Subagent",
			description:
				"Launch a Pi subagent in a legacy Herdr pane or local Core terminal. " +
				"Managed worktrees require legacy Herdr; Core runs in the background without Desktop Agents tabs or sidebar integration. " +
				"Use an ordinary child for read-only work and a single writer, and worktrees only for parallel writers. " +
				"A worktree starts from the committed HEAD, without uncommitted parent changes, and is retained after the run for parent review. " +
				"To inspect one, use an ordinary child with cwd set to its path. " +
				"The call returns at once and the result arrives later as a new message. " +
				"Do not poll or guess the result; end the turn or do other independent work.",
			promptSnippet:
				"Launch a Pi subagent in Herdr or Core; its result arrives later as a new message",
			promptGuidelines: subagentRoutingGuidelines,
			parameters: SubagentParams,

			async execute(_toolCallId, params, _signal, _onUpdate, ctx) {
				const depthRefusal = delegationDepthRefusal(spawningConfig.maxDepth);
				if (depthRefusal) {
					return {
						content: [{ type: "text", text: depthRefusal.message }],
						details: { error: depthRefusal.code },
					};
				}

				// Prevent a named role from spawning another instance of itself unless
				// its definition opted in with `self-spawn: true`. This is a role-design
				// default, not a recursion boundary: role A can still launch role B,
				// which can launch role A.
				const currentAgent = process.env.PI_SUBAGENT_AGENT;
				if (
					params.agent &&
					currentAgent &&
					params.agent === currentAgent &&
					process.env.PI_SUBAGENT_SELF_SPAWN !== "1"
				) {
					return {
						content: [
							{
								type: "text",
								text: `You are the ${encodeHostValue(currentAgent)} agent — do not start another ${encodeHostValue(currentAgent)}. You were spawned to do this work yourself. Complete the task directly.`,
							},
						],
						details: { error: "self-spawn blocked" },
					};
				}

				const catalog = params.agent
					? discoverAgentCatalog(runtime.pi)
					: undefined;
				const roleDiagnostic =
					catalog &&
					!catalog.agents.some((agent) => agent.name === params.agent)
						? catalog.diagnostics.find(
								(candidate) =>
									candidate.agentName === params.agent &&
									(candidate.code === "external-cli-unsupported" ||
										candidate.code === "invalid-capability-declaration"),
							)
						: undefined;
				if (roleDiagnostic) {
					return {
						content: [
							{
								type: "text",
								text: `Error: ${encodeHostValue(roleDiagnostic.message, HOST_ERROR_CHARS)}`,
							},
						],
						details: { error: roleDiagnostic.code },
					};
				}

				const agentDefs = params.agent
					? loadAgentDefaults(params.agent, runtime.pi)
					: null;
				const persistent = resolveEffectivePersistent(params, agentDefs);
				if (params.accept) {
					// Before any Herdr resource: v1 checks only auto-exit ordinary runs.
					normalizeAcceptSpec(params.accept);
					const refusal = acceptLaunchRefusal({
						persistent,
						autoExit: resolveEffectiveAutoExit(params, agentDefs),
					});
					if (refusal)
						return {
							content: [{ type: "text", text: `Error: ${refusal}` }],
							details: { error: "accept-unsupported" },
						};
				}
				const notifyRefusal = notifyLaunchRefusal({
					persistent,
					notify: params.notify,
				});
				if (notifyRefusal)
					return {
						content: [{ type: "text", text: `Error: ${notifyRefusal}` }],
						details: { error: "notify-unsupported" },
					};
				const capError = persistent ? persistentCapacityError() : undefined;
				if (capError) {
					return {
						content: [{ type: "text", text: capError }],
						details: { error: "persistent-cap" },
					};
				}

				// Validate prerequisites
				if (!runtime.session!.availability().available) {
					return muxUnavailableResult(runtime);
				}

				if (!ctx.sessionManager.getSessionFile()) {
					return {
						content: [
							{
								type: "text",
								text: "Error: no session file. Start pi with a persistent session to use subagents.",
							},
						],
						details: { error: "no session file" },
					};
				}

				// Launch the subagent (creates pane, sends command)
				const parentThinking = pi.getThinkingLevel();
				if (
					parentThinking !== "off" &&
					parentThinking !== "minimal" &&
					parentThinking !== "low" &&
					parentThinking !== "medium" &&
					parentThinking !== "high" &&
					parentThinking !== "xhigh" &&
					parentThinking !== "max"
				) {
					throw new Error(
						`Unsupported parent thinking level: ${parentThinking}`,
					);
				}
				const runtimePlans = resolveSubagentRuntimePlans(
					params,
					ctx,
					parentThinking,
				);
				runtime.latestCtx = ctx;
				// A running tool proves this load's API is live.
				bindLiveApi(runtime, pi);
				const id = randomUUID();
				const attempt = {
					id,
					controlTaskId: id,
					origin: { cwd: ctx.cwd, invocationCwd: process.cwd() },
				};
				const first = normalizePiAttempt(params, ctx, parentThinking, attempt);
				const [plan, ...fallbacks] = runtimePlans;
				if (!plan) throw new Error("No resolved runtime plans");
				const input: PiLaunchInput = {
					...first,
					plans: [plan, ...fallbacks],
					// Fallbacks outlive this tool call; session replacement invalidates ctx.
					// In a reload gap, wait for the replacement's context; never fail a candidate.
					prepareAttempt: async (_index, cancelled) => {
						const live = await awaitLiveContext(runtime, id, cancelled);
						// A cancel recorded while waiting launches nothing, even if the
						// replacement bound its context first.
						if (cancelled.aborted)
							throw new Error("Cancelled before the fallback launch");
						if (!live)
							throw new Error("No live parent context for the fallback launch");
						return normalizePiAttempt(params, live, parentThinking, attempt);
					},
				};
				const session = runtime.session!;
				if (persistent) (runtime.persistentReservations ??= new Set()).add(id);
				let handle;
				try {
					handle = await session.spawnPi(input);
				} finally {
					runtime.persistentReservations?.delete(id);
				}
				const running = session.getRecord(id)!;
				const startedDetails = session.getStarted(id)!;
				// The tool's signal is not a producer signal. Delivery belongs to RunSession.
				void session.supervise(handle, session.getTask(id)!).catch(() => {
					// Delivery failure retains manual panes; no second send or cleanup producer.
					if (!session.getTask(id)) {
						runningSubagents.delete(running.id);
						updateWidget();
					}
				});
				return {
					content: [
						{
							type: "text",
							text: startedDetails.launchFailure
								? `Sub-agent "${encodeHostValue(params.name)}" launch is uncertain. Its acquired owner remains controlled and supervised until termination is confirmed; no fallback will launch. ${encodeHostValue(startedDetails.launchFailure)} Do not blindly relaunch. A result will be delivered automatically after confirmed termination.`
								: `Sub-agent "${encodeHostValue(params.name)}" launched and is now running in the background` +
									(running.worktree
										? ` in worktree ${encodeHostValue(running.worktree.path, HOST_PATH_CHARS)} on branch ${encodeHostValue(running.worktree.branch)}. `
										: ". ") +
									launchDiagnosticsText(
										running.worktree?.diagnostics,
										"",
										" ",
									) +
									`Do NOT generate or assume any results — you have no idea what the sub-agent will do or produce. ` +
									`The results will be delivered to you automatically as a steer message when the sub-agent finishes. ` +
									`Until then, move on to other work or tell the user you're waiting.`,
						},
					],
					details: startedDetails,
				};
			},

			renderCall: renderers?.subagent?.renderCall,

			renderResult: renderers?.subagent?.renderResult,
		});
}

/** The subagent_resume tool. */
export function registerResumeTool(
	pi: ExtensionAPI,
	{
		shouldRegister,
		runtime,
		updateWidget,
		spawningConfig,
		renderers,
	}: Pick<
		LaunchToolDeps,
		| "shouldRegister"
		| "runtime"
		| "updateWidget"
		| "spawningConfig"
		| "renderers"
	>,
): void {
	const runningSubagents = runtime.runningSubagents;

	// ── subagent_resume tool ──
	if (shouldRegister("subagent_resume"))
		pi.registerTool({
			name: "subagent_resume",
			exposure: ROUTINE_TOOL_EXPOSURE,
			label: "Resume Subagent",
			description:
				"Resume a saved subagent session in a new legacy Herdr pane or local Core terminal. " +
				"Use it to continue a cancelled run or send follow-up work. " +
				"It does not reattach a retained worktree; continue that work in the existing workspace. " +
				"The call returns at once and the result arrives later as a message. Do not poll for it.",
			promptSnippet:
				"Resume a saved subagent in Herdr or Core; its result arrives later as a new message",
			parameters: Type.Object({
				sessionPath: Type.String({
					description: "Path to the session .jsonl file to resume",
				}),
				name: Type.Optional(
					Type.String({
						description:
							"Display name for the run (and legacy Herdr tab). Default: 'Resume'",
					}),
				),
				message: Type.Optional(
					Type.String({
						description: "Message to send after resuming.",
					}),
				),
				autoExit: Type.Optional(
					Type.Boolean({
						description:
							"Exit after the response. Defaults to true; set false to leave the session open for the user.",
					}),
				),
			}),

			renderCall: renderers?.subagent_resume?.renderCall,

			renderResult: renderers?.subagent_resume?.renderResult,

			async execute(_toolCallId, params, _signal, _onUpdate, ctx) {
				const name = params.name ?? "Resume";

				const depthRefusal = delegationDepthRefusal(spawningConfig.maxDepth);
				if (depthRefusal) {
					return {
						content: [{ type: "text", text: depthRefusal.message }],
						details: { error: depthRefusal.code },
					};
				}

				if (!runtime.session!.availability().available) {
					return muxUnavailableResult(runtime);
				}

				if (!existsSync(params.sessionPath)) {
					return {
						content: [
							{
								type: "text",
								text: `Error: session file not found: ${encodeHostValue(params.sessionPath, HOST_PATH_CHARS)}`,
							},
						],
						details: { error: "session not found" },
					};
				}

				runtime.latestCtx = ctx;
				// A running tool proves this load's API is live.
				bindLiveApi(runtime, pi);
				const controlTaskId = randomUUID();
				const session = runtime.session!;
				const handle = await session.resumePi({
					taskId: controlTaskId,
					name,
					sessionPath: params.sessionPath,
					message: params.message,
					autoExit: params.autoExit,
				});
				const started = session.getStarted(controlTaskId)!;
				const id = started.id;
				void session
					.supervise(handle, session.getTask(controlTaskId)!)
					.catch(() => {
						if (!session.getTask(controlTaskId)) {
							runningSubagents.delete(id);
							updateWidget();
						}
					});

				return {
					content: [
						{
							type: "text",
							text: started.launchFailure
								? `Session "${encodeHostValue(name)}" resume is uncertain; its owner remains controlled and supervised. No fallback will launch. ${encodeHostValue(started.launchFailure)}`
								: `Session "${encodeHostValue(name)}" resumed.`,
						},
					],
					details: {
						id,
						name,
						sessionPath: params.sessionPath,
						launchScriptFile: started.launchScriptFile,
						status: started.status,
						launchFailure: started.launchFailure,
					},
				};
			},
		});
}

/** The /subagent command: launch a named role, or list roles. */
export function registerSubagentCommand(pi: ExtensionAPI): void {
	// /subagent command — spawn a subagent by name, or list available agents
	pi.registerCommand("subagent", {
		description:
			"Spawn a subagent: /subagent <agent> <task>; list agents: /subagent list",
		handler: async (args, ctx) => {
			const trimmed = args.trim();
			if (trimmed === "list") {
				const catalog = discoverAgentCatalog(pi);
				const lines = [
					...formatVisibleAgentDefinitions(catalog.agents),
					...formatAgentDiagnostics(catalog.diagnostics),
				];
				ctx.ui.notify(
					lines.join("\n") || "No subagent definitions found.",
					"info",
				);
				return;
			}
			if (!trimmed) {
				ctx.ui.notify(
					"Usage: /subagent <agent> [task] | /subagent list",
					"warning",
				);
				return;
			}

			const spaceIdx = trimmed.indexOf(" ");
			const agentName = spaceIdx === -1 ? trimmed : trimmed.slice(0, spaceIdx);
			const task = spaceIdx === -1 ? "" : trimmed.slice(spaceIdx + 1).trim();

			const catalog = discoverAgentCatalog(pi);
			const defs = catalog.agents.find((agent) => agent.name === agentName);
			if (!defs) {
				const diagnostic = catalog.diagnostics.find(
					(candidate) => candidate.agentName === agentName,
				);
				ctx.ui.notify(
					diagnostic
						? encodeHostValue(diagnostic.message, HOST_ERROR_CHARS)
						: missingRoleMessage(agentName),
					"error",
				);
				return;
			}

			const taskText =
				task || `You are the ${agentName} agent. Wait for instructions.`;
			const displayName = agentName[0].toUpperCase() + agentName.slice(1);
			const toolCall = `Use subagent with agent: "${agentName}", name: "${displayName}", task: ${JSON.stringify(taskText)}`;
			pi.sendUserMessage(toolCall);
		},
	});
}
